import torch


def run(tensors, found_inf, inv_scale):
    torch._amp_foreach_non_finite_check_and_unscale_(tensors, found_inf, inv_scale)
    return tensors, found_inf


def gen_inputs(ctx, device):
    import torch

    t_shapes = ctx["tensors__shape"]
    t_dtype = getattr(torch, ctx["tensors__dtype"])
    special = all(len(s) == 1 for s in t_shapes)
    tensors = []
    if special:
        # first tensor carries an inf, second carries a nan
        tensors.append(
            torch.tensor([1.0, 2.0, float("inf"), 4.0], device=device, dtype=t_dtype)
        )
        tensors.append(
            torch.tensor([5.0, 6.0, float("nan"), 8.0], device=device, dtype=t_dtype)
        )
    else:
        for s in t_shapes:
            tensors.append(torch.randn(tuple(s), device=device, dtype=t_dtype))
    found_inf = torch.tensor(0.0, device=device, dtype=torch.float32)
    inv_scale = torch.tensor(2.0, device=device, dtype=torch.float32)
    return {"tensors": tensors, "found_inf": found_inf, "inv_scale": inv_scale}



def _flatten(value):
    if isinstance(value, (list, tuple)):
        leaves = []
        for item in value:
            leaves.extend(_flatten(item))
        return leaves
    return [value]


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch

    ref_leaves = _flatten(ref_outputs)
    sol_leaves = _flatten(sol_outputs)
    if len(ref_leaves) != len(sol_leaves):
        return {"passed": False, "message": "leaf count mismatch", "metrics": {}}
    for r, s in zip(ref_leaves, sol_leaves):
        r = r.detach().to("cpu").to(torch.float64)
        s = s.detach().to("cpu").to(torch.float64)
        if r.shape != s.shape:
            return {
                "passed": False,
                "message": f"shape {s.shape} vs {r.shape}",
                "metrics": {},
            }
        both_nan = torch.isnan(r) & torch.isnan(s)
        both_posinf = torch.isposinf(r) & torch.isposinf(s)
        both_neginf = torch.isneginf(r) & torch.isneginf(s)
        finite = torch.isfinite(r) & torch.isfinite(s)
        close = torch.zeros_like(r, dtype=torch.bool)
        close[finite] = (
            (r[finite] - s[finite]).abs() <= 1e-2 + 1e-2 * r[finite].abs()
        )
        if not (close | both_nan | both_posinf | both_neginf).all().item():
            return {"passed": False, "message": "value mismatch", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
